44	// 连续三帧各增加一个微小正转角：第三帧朝向按正常浮点加法累积到约 3e-16；
45	// 负增量累积到对应负方向。
46	func TestTinyHeadingAccumulates(t *testing.T) {
47		cases := []struct {
48			name string
49			step float64
50			want float64
51		}{
52			{"positive", tinyHeading, 3e-16},
53			{"negative", -tinyHeading, -3e-16},
54		}
55		for _, tc := range cases {
56			t.Run(tc.name, func(t *testing.T) {
57				m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
58				frames := make([]Frame, 3)
59				for i := range frames {
60					frames[i] = Frame{Time: int64(10 * (i + 1)), DHeading: tc.step}
61				}
62				res, err := m.ImportSegment(Segment{ID: "s", Frames: frames})
63				if err != nil {
64					t.Fatalf("ImportSegment: %v", err)
65				}
66				if res.EndPose.Heading != tc.want {
67					t.Fatalf("segment end heading = %v, want %v", res.EndPose.Heading, tc.want)
68				}
69				// 每一帧的历史位姿都应保留累积到当时的朝向。
70				for i := range frames {
71					got, err := m.PoseAt(frames[i].Time)
72					if err != nil {
73						t.Fatalf("PoseAt(%d): %v", frames[i].Time, err)
74					}
75					want := float64(i+1) * tc.step
76					if got.Heading != want {
77						t.Fatalf("PoseAt(%d) heading = %v, want %v", frames[i].Time, got.Heading, want)
78					}
79				}
80				cur, _ := m.CurrentPose()
81				if cur.Heading != tc.want {
82					t.Fatalf("current heading = %v, want %v", cur.Heading, tc.want)
83				}
84			})
85		}
86	}
