104	// 小朝向必须实际参与定位：转向后的下一次前进按运动前朝向旋转，留下与该
105	// 方向一致的横向分量；转向帧中的路标观测按运动完成后的朝向转换，位置也
106	// 带同一横向分量。
107	func TestTinyHeadingDrivesKinematicsAndObservations(t *testing.T) {
108		dir := t.TempDir()
109		path := filepath.Join(dir, "map.pose")
110		m, err := Create(path, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
111		if err != nil {
112			t.Fatalf("Create: %v", err)
113		}
114		// 第 1 帧：原地转向 1e-16，运动完成后在自身坐标正前方 (1,0) 观测路标 L。
115		// 第 2 帧：朝向增量 0，自身坐标前进 1（按运动前朝向 1e-16 转换）。
116		// 第 3 帧：朝向增量 0，朝向继续保持。
117		res, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
118			{Time: 10, DHeading: tinyHeading, Observations: []Observation{{ID: "L", X: 1, Y: 0}}},
119			{Time: 20, DX: 1, DHeading: 0},
120			{Time: 30, DHeading: 0},
121		}})
122		if err != nil {
123			t.Fatalf("ImportSegment: %v", err)
124		}
125		wantX := math.Cos(tinyHeading)
126		wantY := math.Sin(tinyHeading)
