132			t.Fatalf("end pose = (%v,%v), want (%v,%v)", res.EndPose.X, res.EndPose.Y, wantX, wantY)
133		}
134		if res.EndPose.Heading != tinyHeading {
135			t.Fatalf("end heading = %v, want %v", res.EndPose.Heading, tinyHeading)
136		}
137		for _, tm := range []int64{10, 20, 30} {
138			p, err := m.PoseAt(tm)
139			if err != nil {
140				t.Fatalf("PoseAt(%d): %v", tm, err)
141			}
142			if p.Heading != tinyHeading {
143				t.Fatalf("PoseAt(%d) heading = %v, want %v", tm, p.Heading, tinyHeading)
144			}
