189	// 回环校正：锚点原朝向为零、目标位置不变而目标朝向为 1e-16。锚点与后续
190	// 轨迹必须包含这次转向，受影响路标观测随之更新；不能把它误判为几何与
191	// 朝向完全不变的恒等校正。校正记录中的前后值如实反映结果，重开后一致。
192	func TestTinyHeadingLoopCorrection(t *testing.T) {
193		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
194		// 锚点帧 t=10 前进到 (1,0)；末帧 t=20 再前进到 (2,0)，在自身正前方
195		// (1,0) 观测 L，地图坐标 (3,0)。
196		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
197			{Time: 10, DX: 1},
