276		m := newMap(t, Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1})
277		anchorHeading := normalizeAngle(math.Pi - 1e-15) // +π 内侧一个可表示的小角
278		if _, err := m.ImportSegment(Segment{ID: "s", Frames: []Frame{
