298		}
299		if rec.Poses[0].After.Heading != want {
300			t.Fatalf("corrected heading = %v, want boundary-folded %v", rec.Poses[0].After.Heading, want)
301		}
302		if rec.Poses[0].After.X != 0 || rec.Poses[0].After.Y != 0 {
303			t.Fatalf("anchor position changed: (%v,%v)", rec.Poses[0].After.X, rec.Poses[0].After.Y)
304		}
305		// 正 π 始终表示为负 π。
306		if h := rec.Poses[0].After.Heading; h >= math.Pi || h < -math.Pi {
