1043			endIdx := -1
1044			for j := 1; j < len(fd.Trajectory); j++ {
1045				if fd.Trajectory[j].Time == t {
1046					endIdx = j
1047					break
1048				}
1049			}
1050			if endIdx < 0 {
1051				return fmt.Errorf("%w: segment %s records end pose time %d which does not match an imported frame", ErrCorrupt, sg.ID, t)
1052			}
1053			// 数值一致性核对只对末帧及涉及它的校正范围都具有完整逐帧依据的
1054			// 段进行。旧文件缺省 sources、末帧是缺少依据的 null 旧帧、或某一
