package posemap

// replay.go 承载“按每次出现归组观测、保留旧观测贡献、逐条重建位置”的
// 公共重放流程，供提交回环校正（Correct，见 correction.go）与打开地图
// 时的核对（validateLoaded，见 persistence.go）共同使用，保证两种操作
// 对同一份观测流沿用完全一致的规则：
//
//   - 归组：每条观测按所在帧时间归入当时的那次出现（时间边界规则见
//     occurrence.go）；同一标识失效后再次出现时各次出现分别归组，旧
//     出现不参与新出现的合并；失效时间上的观测仍归入旧出现。
//   - 旧贡献：旧地图缺少逐帧依据的观测以文件中保存的次数与平均位置作
//     为固定起点（seed），不补造观测，也不随后续重放改变。
//   - 重建：观测按帧时间升序、同帧按输入次序逐条接纳（单条接纳规则见
//     aggregate.go）：首条观测建立位置，后续观测与当时平均位置比较，
//     距离恰等于合并上限仍接纳、超过才拒绝；位置是全部已接受观测（含
//     固定旧贡献）的等权平均，同帧重复观测各计一次，不能通过改变次序
//     让数值或接受结果变化。
//
// 重放器只持有归组边界与聚合结果；出现编号、有效状态、失效信息等仍由
// 各自流程在重放器之外维护，重放不改变它们。

// occurrenceKey 标识某一路标的某一次出现（出现编号 1 起）。
type occurrenceKey struct {
	id  string
	num int
}

// replayFrame 是一帧的重放输入：帧时间（决定观测归入哪次出现）、转换
// 观测到地图坐标所用的位姿（校正重放时为校正后位姿，打开核对时为文件
// 中的当前位姿）以及该帧的原始观测（自身坐标，按输入次序）。
type replayFrame struct {
	time         int64
	pose         Pose
	observations []Observation
}

// replayRejectReason 区分重放中一条观测无法按规则接纳的原因。
type replayRejectReason int

const (
	replayUnknownLandmark replayRejectReason = iota // 观测的路标没有登记归属边界
	replayNoOccurrence                              // 观测时间不属于该路标的任何一次出现
	replayNonFinite                                 // 转换到地图坐标后为非有限数值
	replayConflict                                  // 与当时平均位置的距离超过合并上限
)

// replayReject 报告重放中第一条无法接纳的观测：所在帧的实际时间、路标
// 标识与归属的出现编号（无法归组时编号为 0）。
type replayReject struct {
	reason replayRejectReason
	time   int64
	id     string
	num    int
}

// observationReplay 是一组路标出现的观测重放器。使用次序：
//
//  1. track 登记各标识历次出现的时间边界；
//  2. seed 登记参与重建的出现及其固定旧观测贡献（只有登记过的出现参与
//     重建；归入未登记出现的观测被跳过——校正只重建受影响的出现，其余
//     出现的观测位置不变）；
//  3. replay 按帧时间升序逐帧逐条重放观测；
//  4. agg 读取各次出现重建出的计数与等权平均位置。
//
// observed 只读取归组边界、不影响聚合，可在上述任何阶段调用。
type observationReplay struct {
	mergeDistance float64
	windows       map[string][]occurrenceWindow
	aggs          map[occurrenceKey]*observationAgg
}

func newObservationReplay(mergeDistance float64) *observationReplay {
	return &observationReplay{
		mergeDistance: mergeDistance,
		windows:       make(map[string][]occurrenceWindow),
		aggs:          make(map[occurrenceKey]*observationAgg),
	}
}

// track 登记一个路标各次出现的时间边界（编号即下标+1）。
func (r *observationReplay) track(id string, wins []occurrenceWindow) {
	r.windows[id] = wins
}

// seed 登记一次出现参与重建，并以其固定旧观测贡献（legacyCount 条、等权
// 平均 (lx,ly)；legacyCount 为 0 表示无旧贡献）作为聚合起点。起点本身
// 不做距离检查（这些观测此前已按同一规则接纳）。
func (r *observationReplay) seed(id string, num, legacyCount int, lx, ly float64) {
	a := &observationAgg{}
	if legacyCount > 0 {
		a.seed(legacyCount, lx, ly)
	}
	r.aggs[occurrenceKey{id: id, num: num}] = a
}

// occurrenceOf 把时间 t 的一次观测归入该路标当时的那次出现，返回 1 起
// 的出现编号；known 为假表示该路标没有登记归属边界，known 为真而返回
// 0 表示该时间不属于它的任何一次出现。
func (r *observationReplay) occurrenceOf(id string, t int64) (num int, known bool) {
	wins, ok := r.windows[id]
	if !ok {
		return 0, false
	}
	return occurrenceNumberAt(wins, t), true
}

// occurrences 返回一个路标登记的出现次数；未登记时返回 0。
func (r *observationReplay) occurrences(id string) int {
	return len(r.windows[id])
}

// observed 归组一段帧序列中实际观测到的（路标，出现编号）：每条观测各
// 归组一次，同一出现只记一次；无法归组的观测（路标未登记或不属于任何
// 出现）不记入。帧序列只需给出时间与观测，位姿不参与归组。
func (r *observationReplay) observed(frames []replayFrame) map[occurrenceKey]struct{} {
	out := make(map[occurrenceKey]struct{})
	for _, fr := range frames {
		for _, ob := range fr.observations {
			if num, known := r.occurrenceOf(ob.ID, fr.time); known && num != 0 {
				out[occurrenceKey{id: ob.ID, num: num}] = struct{}{}
			}
		}
	}
	return out
}

// replay 逐帧重放观测：帧必须按时间升序给出，同帧观测按输入次序逐条
// 接纳。全部接纳返回 nil；否则返回第一条无法接纳的观测（已接纳的观测
// 留在聚合中，由调用方决定整次拒绝后如何处理——两种调用方都在校验全部
// 通过前不触碰真实状态）。
func (r *observationReplay) replay(frames []replayFrame) *replayReject {
	for _, fr := range frames {
		for _, ob := range fr.observations {
			num, known := r.occurrenceOf(ob.ID, fr.time)
			if !known {
				return &replayReject{reason: replayUnknownLandmark, time: fr.time, id: ob.ID}
			}
			if num == 0 {
				return &replayReject{reason: replayNoOccurrence, time: fr.time, id: ob.ID}
			}
			a := r.aggs[occurrenceKey{id: ob.ID, num: num}]
			if a == nil {
				continue // 该次出现未登记：不参与本次重建
			}
			switch a.admit(fr.pose, ob, r.mergeDistance) {
			case obsNonFinite:
				return &replayReject{reason: replayNonFinite, time: fr.time, id: ob.ID, num: num}
			case obsConflict:
				return &replayReject{reason: replayConflict, time: fr.time, id: ob.ID, num: num}
			}
		}
	}
	return nil
}

// agg 返回某次出现当前重建出的聚合（计数与等权平均位置）；该出现未登记
// 时返回 nil。
func (r *observationReplay) agg(id string, num int) *observationAgg {
	return r.aggs[occurrenceKey{id: id, num: num}]
}

package posemap

import "math"

// aggregate.go 承载“同一路标一次出现的观测接纳与合并规则”这一公共业务，
// 供轨迹导入（ImportSegment）与回环校正重放（Correct）共同使用，保证两条
// 流程对同一种观测的转换、接纳、等权平均与计数规则始终一致：
//
//   - 观测先由机器人自身坐标按当时位姿转换到地图坐标（localToMap）；
//   - 转换结果出现非有限数值时，优先按数值异常处理，不降级为距离冲突，
//     也不留到保存时才报普通错误；
//   - 该次出现的第一条观测直接作为平均位置起点、计数 1，不做距离判断；
//   - 其后每条观测与当时的平均位置比较，距离恰好等于合并上限仍可接纳，
//     超过上限则拒绝（且整条操作随之整体拒绝）；
//   - 接纳后位置是全部已接受观测的等权平均，按 mergeMean 增量计算以避免
//     大坐标下 mean*count 溢出，计数按实际接纳次数加一；
//   - 同帧多条观测按输入次序逐条处理，前一条接纳后的平均位置会影响下一
//     条的距离判断，不能先汇总整帧再统一判断。
//
// 聚合器只持有规则本身关心的计数与位置；出现编号、有效状态、失效信息、
// 首次观测时间等仍由各自流程在聚合器之外维护，规则不改变它们。

// obsRejectReason 区分一次观测被拒绝的原因。
type obsRejectReason int

const (
	obsAccepted  obsRejectReason = iota // 接纳（含首次建点）
	obsNonFinite                        // 转换到地图坐标后为非有限数值
	obsConflict                         // 与当时平均位置的距离超过合并上限
)

// observationAgg 是同一路标某一次出现对已接纳观测的增量聚合：等权平均
// 位置 (x,y) 与已接纳条数 count。count 为 0 时该次出现尚未接纳任何观测，
// 此时 (x,y) 无意义，第一条观测只做有限性检查即直接建点。
//
// 两种流程会在重放本段观测之前，先以一组“不在本次重放范围内、但固定有效”
// 的已接受观测作为起点（seed）：
//
//   - 导入时并入一条已有有效出现：该出现此前已提交的观测是固定历史，本段
//     新观测在其当前均值上增量合并；
//   - 回环校正重放旧文件第 1 次出现：旧文件缺少逐帧来源的观测无法重放，
//     其贡献固定为文件中的聚合值（legacyCount 次平均），依据完整的观测再
//     做增量平均。
//
// 起点本身不做距离检查（这些观测此前已按同一规则接纳），只有之后纳入的
// 观测才与（含固定起点在内的）当时平均位置比较。
type observationAgg struct {
	count int
	x     float64
	y     float64
}

// seed 以一组固定的已接受观测（count 条、等权平均 (x,y)）作为聚合起点。
// 调用时聚合器必须为空（尚未接纳任何观测）。
func (a *observationAgg) seed(count int, x, y float64) {
	a.count = count
	a.x = x
	a.y = y
}

// admit 按统一规则接纳一条观测：pose 为该观测所在帧运动完成后（导入）或
// 校正后（回环重放）的地图坐标位姿，ob 为机器人自身坐标下的观测，
// mergeDistance 为合并上限。
//
// 返回 obsAccepted 表示已并入等权平均（或作为第一条观测建点）；否则返回
// obsNonFinite（转换结果非有限，优先于距离冲突）或 obsConflict（距离严格
// 超过上限；恰好等于上限仍接纳）。被拒绝时聚合状态保持不变。
func (a *observationAgg) admit(pose Pose, ob Observation, mergeDistance float64) obsRejectReason {
	mx, my := localToMap(pose.X, pose.Y, pose.Heading, ob.X, ob.Y)
	// 位姿/观测坐标过大时转换可能溢出为 NaN/无穷：无论这是该次出现的
	// 第一条观测还是与既有平均合并，数值异常都优先于距离冲突。
	if !isFinite(mx) || !isFinite(my) {
		return obsNonFinite
	}
	if a.count > 0 {
		// 与当时平均位置比较：恰好等于合并上限仍可接纳，严格超过才拒绝。
		// 被接受观测与均值相距不超过有限的合并上限，二者之差有限，Hypot 不会溢出。
		if math.Hypot(mx-a.x, my-a.y) > mergeDistance {
			return obsConflict
		}
		a.x = mergeMean(a.x, mx, a.count)
		a.y = mergeMean(a.y, my, a.count)
	} else {
		// 首次出现（或该次出现重放到的第一条观测）：从一次观测开始，
		// 平均位置即观测位置、计数 1，不做距离判断。
		a.x, a.y = mx, my
	}
	a.count++
	return obsAccepted
}

		return "posemap: correction id " + e.Landmark + " already saved with different content"
	case RejectNoBasis:
		return "posemap: correction range from " + strconv.FormatInt(e.Time, 10) + " lacks per-frame observation sources"
	default:
		return "posemap: request rejected (" + e.Kind + ")"
	}
}

// 可区分的拒绝原因。
const (
	RejectEmptySegment           = "empty_segment"            // 空批次
	RejectEmptyID                = "empty_id"                 // 空段/路标/校正/失效标识
	RejectEmptyReason            = "empty_reason"             // 失效原因为空
	RejectEmptyLandmarkList      = "empty_landmark_list"      // 失效路标列表为空
	RejectDuplicateLandmarkEntry = "duplicate_landmark_entry" // 失效列表中路标重复
	RejectLandmarkNotFound       = "landmark_not_found"       // 失效的路标从未出现
	RejectLandmarkInactive       = "landmark_inactive"        // 失效的路标当前无有效记录
	RejectInvalidationMismatch   = "invalidation_mismatch"    // 同一失效标识对应不同内容
	RejectNegativeVariance       = "negative_variance"        // 负运动方差或负目标方差
	RejectNonFinite              = "non_finite"               // 非有限数值（NaN/Inf）
	RejectTimeOrder              = "time_order"               // 时间未严格递增或首帧不够晚
	RejectInterval               = "interval_exceeded"        // 相邻位姿间隔超过上限
	RejectLandmarkConflict       = "landmark_conflict"        // 同标识路标超出合并距离
	RejectDuplicateMismatch      = "duplicate_mismatch"       // 同一段标识对应不同内容
	RejectAnchorNotFound         = "anchor_not_found"         // 校正锚点未命中已导入帧
	RejectCorrectionMismatch     = "correction_mismatch"      // 同一校正标识对应不同内容
	RejectNoBasis                = "no_basis"                 // 旧地图缺少逐帧观测来源
)

// 哨兵错误，供 errors.Is 使用。
var (
	// ErrClosed 在已关闭的地图上操作时返回。
	ErrClosed = errors.New("posemap: map is closed")
	// ErrInvalidConfig 在创建地图的配置不合法时返回。
	ErrInvalidConfig = errors.New("posemap: invalid config")
	// ErrInvalidRect 在矩形查询的上下界颠倒时返回。
	ErrInvalidRect = errors.New("posemap: invalid rectangle")
	// ErrNotFound 在查询时间早于初始时间（无任何不晚于它的位姿）时返回。
	ErrNotFound = errors.New("posemap: pose not found")
	// ErrLandmarkNotFound 在按标识查询路标历次出现而该标识从未出现时返回。
	ErrLandmarkNotFound = errors.New("posemap: landmark not found")
	// ErrCorrupt 在数据文件损坏、截断或校验失败时返回。
	ErrCorrupt = errors.New("posemap: corrupt data file")
	// ErrUnsupportedVersion 在数据文件格式版本不受支持时返回。
	ErrUnsupportedVersion = errors.New("posemap: unsupported file format version")
)

// normalizeAngle 把任意角度归一到 [-π, π)。
//
// 已经落在范围内的角度原样返回（零保持零，-π 保持 -π，已经可表示的微小
// 角度也不被当舍入误差丢掉）；只有范围外的角度才按整圈 2π 平移回范围。
// 不能先把角度加上或减去 π 再对所有输入统一取模——例如 1e-16 加 π 后低位
// 被 π 的精度吞掉，再减回 π 时微小转角就变成了零，连续多帧的小转向因此
// 无法累积。
func normalizeAngle(a float64) float64 {
	if a == 0 {
		return 0 // 零保持零，-0 也规范成 +0。
	}
	if -math.Pi <= a && a < math.Pi {
		return a
	}
	// 范围外（含 +π）：平移整圈到 [-π, π)。a 有限且 |a| 可能远大于 2π，
	// math.Mod 的结果落在 (-2π, 2π)，至多再平移一次即入范围；a 为非有限
	// 值时结果为 NaN，由调用方按非有限拒绝。
	a = math.Mod(a+math.Pi, 2*math.Pi)
	if a < 0 {
		a += 2 * math.Pi
	}
	a -= math.Pi
	// 浮点取模在边界上可能恰好落到 +π（例如输入 -π 再小一个最小可表示
	// 转角），+π 不属于 [-π,π)，折回 -π：二者物理方向完全相同。
	if a >= math.Pi {
		a -= 2 * math.Pi
	}
	return a
}

// isFinite 判断数值既不是 NaN 也不是 Inf。
func isFinite(v float64) bool { return !math.IsNaN(v) && !math.IsInf(v, 0) }

